export type Diagnostic = { code: string; source: string; level: 'info' | 'warning' | 'error'; message: string; runId?: string; candidateId?: string };
export type RecordContext = { scope: 'candidate'; candidateId: string; role?: string } | { scope: 'role'; role: string; candidateId?: never } | { scope: 'workspace'; candidateId?: never; role?: never };
export type RecordSubject = { candidateId: string | null; name: string | null; rawRole: string | null; role: string | null };
export type RecordAssociation = { subjects: RecordSubject[]; associationStatus: 'resolved' | 'partial' | 'unknown' | 'workspace'; associationMessages: string[] };
export type DecisionState = 'open' | 'snoozed' | 'decided' | 'closed' | 'cancelled' | 'invalidated' | 'history_review';
export type FollowUpState = 'pending' | 'running' | 'done' | 'failed' | 'uncertain' | 'cancelled';
export type DecisionSource = { runId: string; resultId?: string; recordedAt: string };
export type DecisionAnswer = { text: string; scope: string; authority: string | null; expiresAt: string | null; revision: number; recordedAt: string };
export type DecisionAction = { id: string; label: string; kind: 'sync' | 'external' | 'other'; status: FollowUpState; reason: string | null; evidence: string | null; verification: string | null; decisionRevision: number; updatedAt: string };
export type DecisionHistory = { revision: number; requestId: string; operation: string; at: string; state: DecisionState; reason: string | null; evidence: string | null; source: DecisionSource | null; decision: DecisionAnswer | null; actions: DecisionAction[]; snoozedUntil: string | null; context?: RecordContext };
export type DecisionItem = {
  schemaVersion: 1; id: string; identity: { subjectKey: string; questionKey: string; scope: string }; title: string;
  state: DecisionState; effectiveState: DecisionState; revision: number; createdAt: string; updatedAt: string;
  deadline: string | null; blocking: boolean; snoozedUntil: string | null; reason: string | null;
  sources: DecisionSource[]; decision: DecisionAnswer | null; actions: DecisionAction[]; history: DecisionHistory[]; context?: RecordContext;
  followUp: { status: FollowUpState | 'none'; counts: Record<FollowUpState, number> };
};
export type WorkspaceDecision = DecisionItem & RecordAssociation;
export type HighlightDetailEntry = { label: string; value: string };
export type HighlightRevision = { revision: number; requestId: string | null; expectedRevision: number | null; requestedOccurredAt: string | null; text: string; evidence: string | null; decisionId: string | null; subjectKey: string | null; occurredAt: string; updatedAt: string; correction: string | null; context?: RecordContext; details?: HighlightDetailEntry[] };
export type Highlight = { eventKey: string; text: string; evidence: string | null; decisionId: string | null; subjectKey: string | null; occurredAt: string; updatedAt: string; correction: string | null; previousText?: string | null; revision?: number; history?: HighlightRevision[] | null; context?: RecordContext; details?: HighlightDetailEntry[] };
export type WorkspaceHighlight = Highlight & RecordAssociation & { runId: string | null; trigger: 'manual' | 'scheduled' | 'unknown'; sourceRunIds: string[]; sourceKind?: 'archive'; sourceDocumentId?: string; sourceDocumentLabel?: string; timePrecision?: 'day' | 'instant' };
export type CandidateActivity = { candidateId: string; at: string; precision: 'day' | 'instant'; sourceKind: 'archive' | 'result' };
export type WorkspaceOverview = {
  status: 'ok' | 'missing' | 'stale' | 'error'; updatedAt: string | null; revision: string | null;
  decisions: WorkspaceDecision[] | null; highlights: WorkspaceHighlight[] | null;
  candidateActivity?: CandidateActivity[] | null;
  counts: { open: number | null; snoozed: number | null; history: number | null; followUp: number | null };
  diagnostics: Diagnostic[];
};
export type WorkspaceOverviewSummary = Omit<WorkspaceOverview, 'decisions' | 'highlights' | 'candidateActivity'>;
export type Candidate = { id: string; name: string; role: string; rawRole: string; rating: string | null; rawStatus: string | null; stage: string; conflict: boolean; statuses: string[] };
export type Role = { name: string; priority: string | null; status: string | null; configured: boolean };
export type MaterialCategory = 'resume' | 'archive' | 'brief' | 'other';
export type CandidateDocument = { id: string; path: string | null; label: string; category: MaterialCategory; kind: 'markdown' | 'text' | 'pdf' | 'png' | 'jpeg' | 'doc' | 'docx' | 'rtf' | 'unsupported'; status: 'ok' | 'missing' | 'blocked' | 'error'; message: string | null; size: number | null; filename: string; mimeType: string; downloadOnly: boolean };
export type CandidateProgress = { status: 'ok' | 'missing' | 'partial' | 'error'; message: string | null; records: { documentId: string; label: string; currentStatus: string | null; conclusion: string | null; nextAction: string | null; interviews: { round: string | null; time: string | null; format: string | null; interviewers: string | null; status: string | null }[] }[] };
export type CandidateDetail = {
  candidate: Pick<Candidate, 'id' | 'name' | 'rawRole' | 'role' | 'rawStatus' | 'rating'>;
  background: string;
  notes: string;
  sourceRound: string;
  progress: CandidateProgress;
  documents: CandidateDocument[];
  warnings: string[];
};
export type DocumentContent = { document: CandidateDocument; text: string | null; absolutePath: string };
export type RoleInfo = { contextRevision: string; roles: Role[]; allowedStatuses: string[]; unconfiguredRoles?: { name: string; count: number }[]; roleAliases?: Record<string, string>; configRevision?: string | null; configStatus?: 'ok' | 'missing' | 'error'; ledgerStatus?: 'ok' | 'missing' | 'error' };
export type RoleSetResult = RoleInfo & { changed: boolean; role: string; status: string; backup: string | null };
export type RunStep = { id: string; label: string; status: 'pending' | 'running' | 'completed' | 'skipped' | 'failed'; reason: string | null; updatedAt: string };
export type RunResult = { id: string; stepId: string; candidateId: string; action: string; outcome: string; attention: 'none' | 'notice' | 'decision'; nextAction: string | null; updatedAt: string; decisionId?: string };
export type RunResultInput = Omit<RunResult, 'updatedAt'>;
export type RunResultSummary = { total: number; decisions: number; notices: number; updatedAt: string | null; revision: number };
export type RunResults = { runId: string; updatedAt: string; results: RunResult[] | null; revision: number };
export type RunActivity = { runId: string; revision: number; updatedAt: string; items: RunResult[] | null };
export type Run = {
  schemaVersion: 1;
  id: string;
  workflow: string;
  label: string;
  role: string | null;
  ownerSessionId: string | null;
  status: 'running' | 'waiting' | 'completed' | 'failed' | 'cancelled';
  reason: string | null;
  createdAt: string;
  updatedAt: string;
  steps: RunStep[];
  results: RunResult[] | null;
  resultsRevision: number;
  trigger?: 'manual' | 'scheduled' | 'unknown';
  summaryState?: 'unrecorded' | 'highlights' | 'no_change';
  closingSummary?: string | null;
  highlights?: Highlight[] | null;
  highlightsRevision?: number;
};
export type RunSummary = Omit<Run, 'results' | 'highlights'> & { resultSummary: RunResultSummary | null; highlightCount?: number };
export type RunHighlights = { runId: string; highlights: Highlight[] | null; revision: number; updatedAt: string | null; trigger: 'manual' | 'scheduled' | 'unknown'; summaryState: 'unrecorded' | 'highlights' | 'no_change'; closingSummary: string | null };
export type TaskSelection = { mode: 'live' | 'pinned'; runId: string | null };
export type TaskView = { selection: TaskSelection; run: RunSummary | null; latestRunId: string | null; newerRunId: string | null };
export type RoleScope = 'active' | 'following' | 'all';
export type RoleSelection = { roles: Role[]; selectedRole: Role | null; outsideScope: boolean; selectionMissing: boolean; candidates: Candidate[] | null; total: number | null; stages: { id: string; label: string; count: number | null }[]; label: string };
export type SourceStatus = 'ok' | 'missing' | 'error' | 'stale';
export type SourceState = { status: SourceStatus; updatedAt: string | null };
export type BoardSnapshot = {
  schemaVersion: number;
  workspace: string;
  workspaceKey?: string;
  status: 'ok' | 'partial' | 'error' | 'stale';
  error: { code: string; message: string } | null;
  generatedAt: string;
  ledgerUpdatedAt: string | null;
  contextRevision: string | null;
  candidates: Candidate[] | null;
  stages: { id: string; label: string; count: number | null }[];
  roles: Role[];
  runs: RunSummary[] | null;
  unknownStatuses: { status: string; count: number }[];
  diagnostics: Diagnostic[];
  sources: { ledger: SourceState; context: SourceState; runs: SourceState; config: SourceState };
  workspaceOverview?: WorkspaceOverviewSummary;
};
